#!/usr/bin/env bash
# shellcheck disable=SC2016
# SUT mutation battery for plugins/soleur/test/codeql-main-alert-gate.test.sh (sourced when GATE_MUTANTS=1).
# Each line is `mutate <label> <sed -E expression>`; the harness proves the mutation LANDED (the copy
# differs from the pristine script) and that the suite goes RED against it.
mutate "row1/2: filing never counted, a new alert exits 0" 's/FILED=\$\(\(FILED \+ 1\)\)/FILED=$((FILED + 0))/'
mutate "row2: every alert treated as untracked" 's/if \[\[ "\$hits" -gt 0 \]\]; then/if [[ "$hits" -gt 99 ]]; then/'
mutate "row3: || true on the paginated data fetch" 's/(gh api --paginate .*)\|\| rc=\$\?/\1|| true/'
mutate "row4: no --paginate (first page only)" 's/gh api --paginate/gh api/'
mutate "row5: cap hit on a running check-run is treated as green" 's/degrade "analyze-timeout".*$/break/'
mutate "row6: zero Analyze check-runs counts as green" 's/n_runs" -gt 0 && /n_runs" -ge 0 \&\& /'
mutate "row7: closed issues count as a dedupe signal (state all)" 's/--state open/--state all/'
mutate "row8: dry run still files" 's/if \[\[ "\$DRY_RUN" == "true" \]\]; then/if [[ "$DRY_RUN" == "never" ]]; then/'
mutate "row9: analyses accepted without stability" 's/"\$count" == "\$prev"/"$count" != ""/'
mutate "row9d: analyses count not scoped to the commit sha" 's/select\(\.commit_sha == \$sha\)/select(true)/'
mutate "row10a: rule id anchored with a line anchor" 's/\\\\z/$/'
mutate "row10b: unvalidated rule id used raw" 's/else "invalid-rule-id" end/else . end/'
mutate "row10c: alert text reaches the body" 's/is open on main and has no tracking issue/is open on main @octocat/'
mutate "row11: a non-success Analyze conclusion is ignored" 's/degrade "analyze-not-success".*$/break/'
mutate "row12a: degraded issue never filed" 's/^  list_issues "\$WORK\/degraded-open.json" \|\| return 1$/  return 0/'
mutate "row12b: degraded issue never deduplicated" 's/select\(\.title == \$t\)\]\[0\]/select(.title == "x")][0]/'
mutate "row12c: wrong degraded label" 's/priority\/p2-medium/priority\/p3-low/'
mutate "row14: tracker list not bot-scoped" 's/--author app\/github-actions //'
mutate "row15: sha not validated" 's/^\[\[ "\$SHA" =~ [^|]*\|\| reject_input .*$/true/'
mutate "H3a: severity compared case-sensitively" 's/tostring \| ascii_downcase\) as \$s/tostring) as $s/'
mutate "H3b: PR-ref alerts not ignored" 's/\(\.most_recent_instance\.ref \/\/ "refs\/heads\/main"\) == "refs\/heads\/main"/true/'
mutate "H3c: medium alerts qualify" 's/\$s == "critical" or \$s == "high"/$s != ""/'
mutate "H4a: tracker list bound shrunk to 20" 's/--limit 200/--limit 20/'
mutate "H4b: tracker match is a substring not a number-bounded prefix" 's/select\(test\("\\\\A\[0-9\]"\) \| not\)/select(true)/'
mutate "wait1: oldest run per name used instead of latest" 's/map\(max_by\(\.id\)\)/map(min_by(.id))/'
mutate "wait2: check-runs from any app counted" 's/ and \.app\.slug == "github-actions"//'
mutate "exit1: every RED exit becomes 0" 's/^  exit 1$/  exit 0/'
mutate "bound1: gh calls lose their timeout" 's/timeout 60 //'
mutate "label1: wrong issue priority label" 's/priority\/p1-high/priority\/p0-critical/'
GATE_MUT_ONLY=r12 mutate "row12d: degraded issue loses action-required (the only page for a queue-made push)" 's/ --label priority\/p2-medium --label action-required\)/ --label priority\/p2-medium)/'
GATE_MUT_ONLY=sx mutate "sx: sanitize passes the stderr through untouched" 's/tr -cd [^)]*\)/cat)/'
GATE_MUT_ONLY=w5 mutate "w5: any check-run whose name contains Analyze gates the wait" 's/startswith\("Analyze \("\)/contains("Analyze")/'
GATE_MUT_ONLY=h5 mutate "h5: duplicate alert numbers across pages are not collapsed" 's/ \| unique_by\(\.number\)//'
GATE_MUT_ONLY=d1 mutate "d1a: default MAX_POLLS 50 shrunk to 2" 's/MAX_POLLS:-50/MAX_POLLS:-2/'
GATE_MUT_ONLY=d1 mutate "d1b: default POLL_INTERVAL 30 shrunk to 0" 's/POLL_INTERVAL:-30/POLL_INTERVAL:-0/'
GATE_MUT_ONLY=d1 mutate "d1c: default SETTLE_POLLS 8 shrunk to 1" 's/SETTLE_POLLS:-8/SETTLE_POLLS:-1/'
GATE_MUT_ONLY=d1 mutate "d1d: pause never sleeps" 's/^pause\(\) \{ sleep "\$POLL_INTERVAL"; \}/pause() { :; }/'
GATE_MUT_ONLY=d2 mutate "d2a: the wall-clock deadline is never checked in phase 1" 's/if out_of_time; then degrade "deadline-exceeded" "the wall-clock deadline passed while waiting for the Analyze check-runs"; fi/:/'
GATE_MUT_ONLY=d2 mutate "d2b: the wall-clock deadline is never checked in phase 2" 's/if out_of_time; then degrade "deadline-exceeded" "the wall-clock deadline passed while waiting for the analyses to settle"; fi/:/'
GATE_MUT_ONLY=d2 mutate "d2c: out_of_time ignores the pause that would not fit" 's/SECONDS \+ POLL_INTERVAL/SECONDS/'
GATE_MUT_ONLY=d3 mutate "d3a: phase 2 inherits the phase-1 poll count (shared budget)" '/^prev=""$/{n;s/^POLLS=0$/:/}'
GATE_MUT_ONLY=r15,x1 mutate "x1: unset GH_REPO exits 1 through bash again" 's/^GH_REPO="\$\{GH_REPO-\}"$/GH_REPO="${GH_REPO:?GH_REPO must be set to owner\/repo}"/'
GATE_MUT_ONLY=r15 mutate "x1b: DEADLINE_SECONDS not validated" 's/^\[\[ "\$DEADLINE_SECONDS" =~ [^|]*\|\| reject_input .*$/true/'
GATE_MUT_ONLY=r15 mutate "x1c: SETTLE_POLLS not validated" 's/^\[\[ "\$SETTLE_POLLS" =~ [^|]*\|\| reject_input .*$/true/'
